  function addCollider(x,y,w,h){game.colliders.push({x,y,w,h});} function buildMap(){const W=CONFIG.world;game.colliders=[];const houses=[[315,300,250,180,"#d7b587","#c64e2c"],[915,250,275,190,"#d9b381","#24756b"],[1290,645,210,190,"#c7a36f","#ce5a2f"],[330,1120,250,180,"#d9b98c","#236c67"],[885,1300,300,190,"#c89f6b","#d15c2e"],[1190,1050,205,165,"#d7b383","#216e68"]];houses.forEach(([x,y,w,h])=>addCollider(x,y,w,h));const boulders=[];for(let i=0;i<22;i++){const side=i%4;let x,y;if(side===0){x=rand(50,W-50);y=rand(55,185);}if(side===1){x=rand(50,W-50);y=rand(W-195,W-55);}if(side===2){x=rand(50,210);y=rand(50,W-50);}if(side===3){x=rand(W-210,W-50);y=rand(50,W-50);}boulders.push({x,y,r:rand(15,30)});}game.map={houses,boulders,trees:Array.from({length:34},()=>({x:rand(70,W-70),y:rand(70,W-70),r:rand(11,22)}))};game.map.trees=game.map.trees.filter(q=>!houses.some(([x,y,w,h])=>q.x>x-34&&q.x<x+w+34&&q.y>y-34&&q.y<y+h+34)&&distSq(q.x,q.y,900,900)>235*235);}
