  function moveEntity(a,dx,dy){let moved=false;if(!circleHitsMap(a.x+dx,a.y,a.r)){a.x+=dx;moved=true;}if(!circleHitsMap(a.x,a.y+dy,a.r)){a.y+=dy;moved=true;}return moved;}
  function safePoint(preferred,clear=54){for(let i=0;i<30;i++){const x=preferred.x+rand(-160,160),y=preferred.y+rand(-160,160);if(!circleHitsMap(x,y,CONFIG.actorRadius)&&game.actors.every(a=>a.status!=="active"||distSq(x,y,a.x,a.y)>clear*clear))return{x,y};}return{x:900,y:895};}
