  function countdownStart(){return cinematicDuration()-CINEMATIC_SCENES.at(-1).duration;}
  function startCinematic(mode,countdownOnly=false){if(game.state!==STATE.MENU)return;clearInput();initializeAudio();const c=game.cinematic;c.active=true;c.mode=mode;c.elapsed=countdownOnly?countdownStart():0;c.paused=false;c.token++;game.state=STATE.CINEMATIC;el.menu.classList.add("hidden");el.pause.classList.add("hidden");el.results.classList.add("hidden");el.demoBadge.classList.add("hidden");el.cinematic.classList.remove("hidden");syncMusic();updateCinematicCopy();el.skipCinematic.focus({preventScroll:true});if(!countdownOnly)beep(520,.05,"sine",.025);}
  function finishCinematic(token=game.cinematic.token){const c=game.cinematic;if(game.state!==STATE.CINEMATIC||!c.active||token!==c.token)return;const mode=c.mode;c.active=false;if(mode==="round")c.seen=true;el.cinematic.classList.add("hidden");clearInput();if(mode==="replay"){toMenu();el.story.focus({preventScroll:true});return;}startGameplayRound();}
