  function beginRound(){if(game.state!==STATE.MENU&&game.state!==STATE.RESULTS&&game.state!==STATE.PAUSED)return;const shouldPlayIntro=!game.cinematic.seen&&game.state===STATE.MENU;if(game.state!==STATE.MENU){game.state=STATE.MENU;el.menu.classList.remove("hidden");}startCinematic("round",!shouldPlayIntro);}
