  function toMenu(){clearInput();game.cinematic.active=false;game.cinematic.token++;game.round=null;game.state=STATE.MENU;stopMusic();el.menu.classList.remove("hidden");el.cinematic.classList.add("hidden");el.pause.classList.add("hidden");el.results.classList.add("hidden");el.demoBadge.classList.add("hidden");hideNotice();updateSetup();updateHud();}
  function pauseGame(reason){if(game.state!==STATE.PLAYING)return;clearInput();game.state=STATE.PAUSED;stopMusic();el.pause.classList.remove("hidden");if(reason)showNotice(reason,3);} function resumeGame(){if(game.state!==STATE.PAUSED||document.hidden)return;initializeAudio();game.state=STATE.PLAYING;syncMusic();el.pause.classList.add("hidden");hideNotice();}

  function orderedActors(){return [...game.actors].sort((a,b)=>b.score-a.score||b.treasure-a.treasure||b.kills-a.kills||a.deaths-b.deaths||a.creation-b.creation);} function actorLabel(a){return a.kind==="human"?t("you"):`${t("bot")} ${a.index}`;} function rankingRow(a,index){return `<li class="${a.kind==="human"?"you":""}"><span>${index+1}. ${actorLabel(a)}</span><strong> ${a.score}</strong></li>`;} function updateRankings(force=false){if(!force&&game.rankingClock<.25)return;game.rankingClock=0;const rank=orderedActors();const humanIndex=rank.indexOf(game.player)+1;el.rank.textContent=`${humanIndex} / ${rank.length}`;el.liveRanking.innerHTML=rank.map(rankingRow).join("");}
  function finalizeThefts(){for(const theft of [...game.thefts])resolveTheft(theft,"return");}
  function endRound(){if(game.state!==STATE.PLAYING)return;clearInput();finalizeThefts();stopMusic();el.demoBadge.classList.add("hidden");game.elapsed=CONFIG.duration;game.state=STATE.RESULTS;const best=Math.max(getBest(),game.player.score);prefs.records[recordKey()]=best;persist();const ranking=orderedActors();el.finalScore.textContent=game.player.score;el.treasureResult.textContent=game.player.treasure;el.defeatedResult.textContent=game.player.kills;el.deathsResult.textContent=game.player.deaths;el.bestResult.textContent=best;el.bestMenu.textContent=best;el.demoResult.classList.toggle("hidden",!game.round.demo);el.finalRanking.innerHTML=ranking.map(rankingRow).join("");el.results.classList.remove("hidden");updateRankings(true);updateHud();}

  function active(a){return a&&a.status==="active";} function currentWeapon(a){return a.special&&a.weaponMode!=="basic"?a.special:"sling";} function difficulty(){return game.round?.profile||DIFFICULTIES.easy;}
  function addParticles(x,y,color,count,speed){if(game.reducedMotion)count=Math.min(count,2);for(let i=0;i<count&&game.particles.length<CONFIG.particleCap;i++){const angle=rand(0,Math.PI*2),velocity=rand(speed*.35,speed);game.particles.push({x,y,vx:Math.cos(angle)*velocity,vy:Math.sin(angle)*velocity,life:rand(.2,.5),max:.5,color,size:rand(2,4)});}}
  function text(x,y,message,color="#fff3bc"){if(game.texts.length<35)game.texts.push({x,y,text:message,life:.9,color});}
