  function trackMusicSource(source){game.music.sources.add(source);source.addEventListener("ended",()=>game.music.sources.delete(source));return source;}
  function scheduleTone(time,freq,duration,volume,type="triangle",detune=0){if(!game.audio)return;try{const o=trackMusicSource(game.audio.createOscillator()),g=game.audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);o.detune.setValueAtTime(detune,time);g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(volume,time+.018);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g).connect(game.audio.musicGain);o.start(time);o.stop(time+duration+.03);}catch(_){}}
