  const MUSIC_MELODY=Object.freeze([0,2,3,5,3,2,0,2, 5,7,8,7,5,3,2,0, 0,2,5,7,8,7,5,3, 2,3,5,3,2,0,2,5, 7,8,10,8,7,5,3,2, 0,2,3,5,7,5,3,2, 5,7,8,10,8,7,5,3, 2,0,2,3,5,3,2,0]);
