  function scheduleMusicLoop(token){if(!game.music.active||token!==game.music.token||!game.audio)return;const start=game.audio.currentTime+.08,step=.375,scale=[220,247,262,294,330,349,392,440,494,523,587];for(let i=0;i<MUSIC_MELODY.length;i++){const note=MUSIC_MELODY[i],time=start+i*step; scheduleTone(time,scale[note],.23,.035,i%7===4?"sine":"triangle",i%4===0?-4:0);if(i%4===0)scheduleDrum(time,"kick");else if(i%4===2)scheduleDrum(time,"hat");}for(let i=0;i<MUSIC_BASS.length;i++){const note=MUSIC_BASS[i];if(note!==null)scheduleTone(start+i*.75,scale[note]/2,.52,.055,"sine",-8);}game.music.timer=window.setTimeout(()=>scheduleMusicLoop(token),24000);}
  function stopMusic(){const music=game.music;if(!music.active&&!music.timer&&!music.sources.size)return;music.token++;music.active=false;if(music.timer){clearTimeout(music.timer);music.timer=0;}if(game.audioReady&&game.audio)rampGain(game.audio.musicGain,0,.12);for(const source of music.sources){try{source.stop();}catch(_){}}music.sources.clear();}
